from dataclasses import dataclass
from typing import Optional


@dataclass
class RunningStats:
    count: int = 0
    total: float = 0.0
    sq_total: float = 0.0
    _min: Optional[float] = None
    _max: Optional[float] = None

    def update(self, x: float) -> None:
        self.count += 1
        self.total += x
        self.sq_total += x * x
        if self._min is None or x < self._min:
            self._min = x
        if self._max is None or x > self._max:
            self._max = x

    @property
    def mean(self) -> float:
        return self.total / self.count if self.count else 0.0

    @property
    def variance(self) -> float:
        if self.count < 2:
            return 0.0
        m = self.mean
        return self.sq_total / self.count - m * m

    def snapshot(self) -> dict:
        return {
            "count": self.count,
            "mean": self.mean,
            "variance": self.variance,
            "min": self._min,
            "max": self._max,
        }
